script.source:
if (ctx.result !== "miss" || H.condition.has(actor, "ready")) return false;
if (!(await H.ask.confirm({
  title: "Resolute", bodyHtml: "Become <strong>Ready</strong> (Resolute)?",
  yesLabel: "Become Ready", noLabel: "Skip",
}))) return false;
await H.condition.set(actor, "ready", true);
await H.chat.post(`${actor.name} becomes Ready (Resolute).`, actor);
